-- K-9 fin — 금융·소득세 클러스터 16종 policy_constants 84행 (적용: MCP apply_migration k9_fin_policy_constants_2026_09_17)
-- 국가법령정보센터 DRF target=eflaw 현행본 XML 원문 직접 대조(2026-09-17). 뉴스·블로그 근거 없음.
--   소득세법 MST 280405 @2026-07-01 · 시행령 286211 @2026-07-01 · 시행규칙 286379 @2026-07-01
--   국세기본법 288571 @2026-08-11 · 시행령 283623 @2026-07-01 · 조특법 280409 @2026-07-01
--   시행예정 대조: 소득세법 MST 280405 @2027-01-01 (div_grossup_2027 · crypto_*)
-- 재사용(이 파일에서 건드리지 않음): int_tax_income 14% · int_tax_local 10%
-- 접두: retinc_ pension_ fin_comp_ div_ etf_ isa_ wh_ daily_ crypto_ penalty_ rent_ deemed_rent_
--   가산세 penalty_ / 연금 pension_ 분리(pen_ 공유 금지). 기존 접두 23종과 겹침 없음(2026-09-17 실측).
-- ⚠️ numbers 첫 원소는 page.tsx 파서 형식: "N%" / "N억원"·"N만원"·"N원". 한 행에 수 하나.
-- ⚠️ 시행예정 행(div_grossup_2027 · crypto_*)도 effective_from 으로 구분해 싣는다 — 계산기가 from 을 읽어 「미시행」을 표기.
-- 말미 단언: 84행 존재 · 새 접두 아래 이 84행 외 0행 · 재사용 int_tax_* 2행. 불일치 시 RAISE → 전체 롤백.

DO $$
DECLARE
  c int;
  k text[] := ARRAY['retinc_svc_le5','retinc_svc_6_10','retinc_svc_11_20','retinc_svc_gt20','retinc_conv_t1','retinc_conv_t2','retinc_conv_t3','retinc_conv_t4','retinc_conv_b1','retinc_conv_b2','retinc_conv_b3','retinc_conv_b4','retinc_conv_b5','pension_ret_le10','pension_ret_11_20','pension_ret_gt20','pension_ded_t1','pension_ded_t2','pension_ded_t3','pension_ded_b1','pension_ded_b2','pension_ded_b3','pension_ded_b4','pension_ded_cap','pension_basic_ded','pension_std_credit','pension_priv_lt70','pension_priv_70_79','pension_priv_80','pension_priv_life','pension_priv_sep_cap','pension_priv_sep_opt','fin_comp_threshold','div_grossup','div_grossup_2027','div_tax_income','etf_ovs_basic_ded','etf_ovs_rate','isa_taxfree_general','isa_taxfree_low','isa_excess_rate','wh_biz_rate','wh_oth_rate','wh_oth_exp60','wh_oth_exp80','wh_oth_min','wh_small_exempt','daily_wage_ded','daily_wh_rate','daily_wh_credit','crypto_basic_ded','crypto_rate','penalty_nofile','penalty_nofile_fraud','penalty_under','penalty_under_fraud','penalty_late_daily','penalty_late_monthly','penalty_notice','penalty_monthly_min','penalty_cut_late_1m','penalty_cut_late_3m','penalty_cut_late_6m','penalty_cut_amend_1m','penalty_cut_amend_3m','penalty_cut_amend_6m','penalty_cut_amend_12m','penalty_cut_amend_18m','penalty_cut_amend_24m','rent_sep_rate','rent_sep_exp_reg','rent_sep_exp_unreg','rent_sep_ded_reg','rent_sep_ded_unreg','rent_sep_other_cap','rent_sep_revenue_cap','rent_small_cut_1','rent_small_cut_1_long','rent_small_cut_2','rent_small_cut_2_long','deemed_rent_rate','deemed_rent_ratio','deemed_rent_base','deemed_rent_2house_base'];
BEGIN
  SELECT count(*) INTO c FROM policy_constants WHERE key = ANY(k);
  IF c <> 84 THEN RAISE EXCEPTION 'k9_fin: expected 84 rows, got %', c; END IF;
  SELECT count(*) INTO c FROM policy_constants
   WHERE key ~ '^(retinc_|pension_|fin_comp_|div_|etf_|isa_|wh_|daily_|crypto_|penalty_|rent_|deemed_rent_)' AND NOT (key = ANY(k));
  IF c <> 0 THEN RAISE EXCEPTION 'k9_fin: unexpected rows under new prefixes: %', c; END IF;
  SELECT count(*) INTO c FROM policy_constants WHERE key IN ('int_tax_income','int_tax_local');
  IF c <> 2 THEN RAISE EXCEPTION 'k9_fin: reused int_tax_* rows missing: %', c; END IF;
END $$;
